const int32 gnAnimTagCount = sizeof(tAnimTagInfo) / sizeof(tAnimTagInfo[0]);

LPCSTR AnimTagGetName(const uint32 dwTagId)
{
    for (int32 i = 0; i < gnAnimTagCount; i++)
    {
        const AxeTagInfo * tTagInfo = &tAnimTagInfo[i];
        if (tTagInfo->dwTagId == dwTagId)
        {
            return tTagInfo->szName;
        }
    }

    return "[Unknown Anim Tag]";
}



uint32 AnimTagGetID(LPCSTR szTagName)
{
    for (int32 i = 0; i < gnAnimTagCount; i++)
    {
        const AxeTagInfo * tTagInfo = &tAnimTagInfo[i];
        if (strcasecmp(tTagInfo->szName, szTagName) == 0)
        {

            return tTagInfo->dwTagId;
        }
    }

    return 0xffffffff;
}


void AnimTagGetStartAndEndTags(const uint32 dwAnimTag,
                               uint32 & uAnimTagStart,
                               uint32 & uAnimTagEnd)
{
    for (int32 i = 0; i < gnAnimTagCount; i++)
    {
        const AxeTagInfo * tTagInfo = &tAnimTagInfo[i];
        if (tTagInfo->dwTagId == dwAnimTag)
        {
            uAnimTagStart = tTagInfo->nTagData0;
            uAnimTagEnd = tTagInfo->nTagData1;
            return;
        }
    }

    uAnimTagStart = 0xffffffff;
    uAnimTagEnd = 0xffffffff;
}



void AnimTagGetAdditionalTag(const uint32 dwAnimTag,
                             uint32 & uAnimAdditionalTag)
{
    for (int32 i = 0; i < gnAnimTagCount; i++)
    {
        const AxeTagInfo * tTagInfo = &tAnimTagInfo[i];
        if (tTagInfo->dwTagId == dwAnimTag)
        {
            uAnimAdditionalTag = tTagInfo->nTagData2;
            return;
        }
    }

    uAnimAdditionalTag = 0xffffffff;
}






