const int sgnDeathAnimTableCount = sizeof(sgtDeathAnimTable) / sizeof(sgtDeathAnimTable[0]);



BOOL AnimIsDeathAnim(uint32 uAnimTag)
{
    for (int32 i = 0; i < sgnDeathAnimTableCount; i++)
    {

        if (sgtDeathAnimTable[i].dwDeathAnimTag == uAnimTag ||
            sgtDeathAnimTable[i].dwDeadAnimTag == uAnimTag)
        {
            return TRUE;
        }
    }

    return FALSE;
}
